namespace PhoneShopErp.Modules.Tenancy.Application;

public interface ITenantService
{
    /// <summary>
    /// Creates a tenant and its bootstrap owner membership. The tenant identifier
    /// is generated by the server; a caller can never supply one.
    /// </summary>
    Task<TenantSummary> CreateAsync(
        TenantOwnerProfile owner,
        CreateTenantRequest request,
        string idempotencyKey,
        CancellationToken cancellationToken);

    Task<TenantSummary> GetAsync(Guid tenantId, CancellationToken cancellationToken);

    Task<TenantSummary> SuspendAsync(
        Guid tenantId,
        string reason,
        CancellationToken cancellationToken);

    Task<TenantSummary> ReactivateAsync(
        Guid tenantId,
        string reason,
        CancellationToken cancellationToken);
}

public interface IOrganisationService
{
    Task<Page<LegalEntitySummary>> ListLegalEntitiesAsync(
        PageRequest page,
        CancellationToken cancellationToken);

    Task<LegalEntitySummary> CreateLegalEntityAsync(
        CreateLegalEntityRequest request,
        string idempotencyKey,
        CancellationToken cancellationToken);

    Task<LegalEntitySummary> UpdateLegalEntityAsync(
        Guid legalEntityId,
        UpdateLegalEntityRequest request,
        CancellationToken cancellationToken);

    Task<Page<BranchSummary>> ListBranchesAsync(PageRequest page, CancellationToken cancellationToken);

    Task<BranchSummary> CreateBranchAsync(
        CreateBranchRequest request,
        string idempotencyKey,
        CancellationToken cancellationToken);

    Task<BranchSummary> UpdateBranchAsync(
        Guid branchId,
        UpdateBranchRequest request,
        CancellationToken cancellationToken);

    Task<Page<StockLocationSummary>> ListStockLocationsAsync(
        PageRequest page,
        CancellationToken cancellationToken);

    Task<StockLocationSummary> CreateStockLocationAsync(
        CreateStockLocationRequest request,
        string idempotencyKey,
        CancellationToken cancellationToken);

    Task<Page<RegisterSummary>> ListRegistersAsync(
        PageRequest page,
        CancellationToken cancellationToken);

    Task<RegisterSummary> CreateRegisterAsync(
        CreateRegisterRequest request,
        string idempotencyKey,
        CancellationToken cancellationToken);
}
